89	    default String toFiscalYear(Owner owner) {
90	        LocalDate registrationDate = owner.getRegistrationDate();
91	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
92	    }
93	
94	    /**
95	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
96	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
97	     * just the last name.
98	     */
99	    default String toSalutation(Owner owner) {
100	        String lastName = owner.getLastName();
101	        String title = owner.getTitle();
102	        if (title == null || title.isBlank()) {
103	            return lastName;
104	        }
105	        return title + " " + lastName;
106	    }
107	
108	    /**
109	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
110	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
111	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
112	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
113	     */
114	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
115	        LocalDate birthDate = owner.getBirthDate();
116	        if (birthDate == null) {
117	            return null;
118	        }
119	        LocalDate reference = owner.getRegistrationDate() != null
120	            ? owner.getRegistrationDate() : LocalDate.now();
121	        int age = Period.between(birthDate, reference).getYears();
122	        if (age < 18) {
123	            return OwnerDto.AgeBandEnum.MINOR;
124	        }
125	        if (age < 65) {
126	            return OwnerDto.AgeBandEnum.ADULT;
127	        }
128	        return OwnerDto.AgeBandEnum.SENIOR;
129	    }
130	
131	    /**
132	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
133	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
134	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
135	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
136	     *
137	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
138	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
139	     * code, a two-digit country code is assumed (the most common length).
140	     */
141	    default String toTelephoneDisplay(Owner owner) {
142	        String telephone = owner.getTelephone();
143	        if (telephone == null || !telephone.startsWith("+")) {
144	            return telephone;
145	        }
146	        String digits = telephone.substring(1);
147	        String code = E164PhoneNumbers.countryCode(digits)
148	            .filter(c -> digits.length() > c.length())
149	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
150	        String national = digits.substring(code.length());
151	        StringBuilder sb = new StringBuilder("+").append(code);
152	        for (int i = 0; i < national.length(); i += 3) {
153	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
154	        }
155	        return sb.toString();
156	    }
157	
158	    /**
159	     * Derive an owner's check digit: a single Luhn check digit (0-9) computed over the digits
160	     * contained in the {@code customerCode}. Non-digit characters (the separators) are ignored.
161	     */
162	    default Integer toCheckDigit(Owner owner) {
163	        String code = owner.getCustomerCode();
164	        if (code == null) {
165	            return null;
166	        }
167	        int sum = 0;
168	        boolean dbl = true;
169	        for (int i = code.length() - 1; i >= 0; i--) {
170	            char c = code.charAt(i);
171	            if (c < '0' || c > '9') {
172	                continue;
173	            }
174	            int d = c - '0';
175	            if (dbl) {
176	                d *= 2;
177	                if (d > 9) {
178	                    d -= 9;
179	                }
180	            }
181	            sum += d;
182	            dbl = !dbl;
183	        }
184	        return (10 - (sum % 10)) % 10;
185	    }
186	
187	    /**
188	     * Derive an owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64
189	     * characters) of the normalized E.164 telephone, the lower-cased email (empty when none) and the
190	     * American Soundex code of the last name, joined with {@code '|'}. Two owners are duplicates only
191	     * when their whole identity keys are equal.
192	     *
193	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
194	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
195	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}, and the Soundex and
196	     * hashing come from {@link IdentityKeyUtils}, the same helpers the soft-match uses.
197	     */
198	    default String toIdentityKey(Owner owner) {
199	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
200	        String email = hasEmail(owner) ? owner.getEmail() : "";
201	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
202	        return IdentityKeyUtils.sha256Hex(telephone + "|" + email + "|" + soundex);
203	    }
204	
205	    /**
206	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
207	     * for the "is an email present" rule shared by the derived fields below.
208	     */
209	    default boolean hasEmail(Owner owner) {
210	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
211	    }
212	
213	    /**
214	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
215	     * otherwise 'PHONE'.
216	     */
217	    default String toContactPreference(Owner owner) {
218	        return hasEmail(owner) ? "EMAIL" : "PHONE";
219	    }
220	
221	    /**
222	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
223	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
224	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
225	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
226	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
227	     * and no namesakes in a single-member household scores 3 points.
228	     */
229	    default Integer toMembershipPoints(Owner owner) {
230	        int points = 0;
231	        if (hasEmail(owner)) {
232	            points += 2;
233	        }
234	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
235	        if (noNamesakes) {
236	            points += 1;
237	        }
238	        if (hasHouseholdBonus(owner)) {
239	            points += 2;
240	        }
241	        if (hasTenureBonus(owner)) {
242	            points += 3;
243	        }
244	        return points;
245	    }
246	
247	    /**
248	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
249	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
250	     * Returns {@code false} when no household size is present (e.g. legacy records).
251	     */
252	    default boolean hasHouseholdBonus(Owner owner) {
253	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
254	    }
255	
256	    /**
257	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
258	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
259	     * or more.
260	     *
261	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
262	     * owner's membership level cannot exceed one above the current maximum membership level among their
263	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
264	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
265	     * member, or a legacy record) the uncapped level stands.
266	     */
267	    default Integer toMembershipLevel(Owner owner) {
268	        int level = uncappedMembershipLevel(owner);
269	        Integer cap = owner.getMembershipLevelCap();
270	        if (cap != null && level > cap) {
271	            return cap;
272	        }
273	        return level;
274	    }
275	
276	    /**
277	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
278	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
279	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
280	     */
281	    default Integer uncappedMembershipLevel(Owner owner) {
282	        int points = toMembershipPoints(owner);
283	        if (points <= 1) {
284	            return 1;
285	        }
286	        if (points <= 3) {
287	            return 2;
288	        }
289	        if (points <= 5) {
290	            return 3;
291	        }
292	        return 4;
293	    }
294	
295	    /**
296	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
297	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
298	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
299	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
300	     * no registration date is present.
301	     */
302	    default boolean hasTenureBonus(Owner owner) {
303	        LocalDate registrationDate = owner.getRegistrationDate();
304	        if (registrationDate == null) {
305	            return false;
306	        }
307	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
308	    }
309	
310	    /**
311	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
312	     */
313	    Map<String, String> CITY_REGION = Map.of(
314	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
315	
316	    /**
317	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
318	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
319	     * inclusive.
320	     */
321	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
322	        "NSW", new int[] {2000, 2099},
323	        "VIC", new int[] {3000, 3099},
324	        "QLD", new int[] {4000, 4099});
325	
326	    /**
327	     * Derive an owner's locality (region) from the region-and-hash customer code: the {@code <REGION>}
328	     * segment of the {@code customerCode}, i.e. everything before the first {@code '-'}. Since the
329	     * region is baked into the customer code at creation (see the create endpoint), the locality now
330	     * moves with that identity rather than being recomputed from the postcode and city. When an owner
331	     * has no customer code yet (e.g. legacy records), fall back to deriving the region directly via
332	     * {@link #regionOf(Owner)}.
333	     */
334	    default String toLocality(Owner owner) {
335	        String code = owner.getCustomerCode();
336	        if (code != null) {
337	            int dash = code.indexOf('-');
338	            if (dash > 0) {
339	                return code.substring(0, dash);
340	            }
341	        }
342	        return regionOf(owner);
343	    }
344	
345	    /**
346	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
347	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
348	     */
349	    Map<String, String> REGION_TIMEZONE = Map.of(
350	        "NSW", "Australia/Sydney",
351	        "VIC", "Australia/Melbourne",
352	        "QLD", "Australia/Brisbane");
353	
354	    /**
355	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
356	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
357	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
358	     */
359	    default String toTimezone(Owner owner) {
360	        return REGION_TIMEZONE.get(toLocality(owner));
361	    }
362	
363	    /**
364	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
365	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
366	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
367	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
368	     * the {@code <REGION>} segment of a new owner's customer code and, through it, the owner's locality.
369	     */
370	    default String regionOf(Owner owner) {
371	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
372	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
373	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
374	        String postcode = owner.getPostcode();
375	        if (postcode != null) {
376	            try {
377	                int value = Integer.parseInt(postcode.trim());
378	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
379	                    int[] range = entry.getValue();
380	                    if (value >= range[0] && value <= range[1]) {
381	                        return entry.getKey();
382	                    }
383	                }
384	            }
385	            catch (NumberFormatException ignored) {
386	                // Non-numeric postcode: fall back to the city table below.
387	            }
388	        }
389	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
390	    }
391	
392	    Owner toOwner(OwnerDto ownerDto);
393	
394	    @Mapping(target = "id", ignore = true)
395	    @Mapping(target = "pets", ignore = true)
396	    Owner toOwner(OwnerFieldsDto ownerDto);
397	
398	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
399	
400	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
401	
402	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
403	        OwnerPageDto ownerPageDto = new OwnerPageDto();
404	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
405	        ownerPageDto.setPage(ownerPage.getNumber());
406	        ownerPageDto.setSize(ownerPage.getSize());
407	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
408	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
409	        return ownerPageDto;
410	    }
411	}
