        if (birthDate == null) {
            return null;
        }
        LocalDate reference = owner.getRegistrationDate() != null
            ? owner.getRegistrationDate() : LocalDate.now();
        int age = Period.between(birthDate, reference).getYears();
        if (age < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
